#include "stdafx.h"#include "ControlBuilder.h"#include "stateKeys.h"#include "./../../HoneyWell/Include/StateSer.h"static const DWORD s_CurVersion = 0x00000011;DWORD KControlBuilder::GetLastVersion(){  return s_CurVersion;}int KControlBuilder::SaveState( IStateSer *psaver ){  OutputDebugString( "KControlBuilder::SaveState...\n" );  DWORD s = GetTickCount();  if( m_entryModule )  {    SaveState( psaver, m_entryModule );    psaver->Write( kKeyEnd );  }  DWORD d = GetTickCount() - s;  char szDebug[64];  sprintf_s( szDebug, "время сохранения состояния ControlBuilder %d ms\n", d );  OutputDebugString( szDebug );  return 0;}void KControlBuilder::SaveState( IStateSer *psaver, SH_Module *pM ){  SaveStateVars( psaver, pM );  for( size_t i=0; i < pM->nSubModules; ++i )  {    SaveState( psaver, pM->ppSubModules[i] );  }  for( size_t i=0; i < pM->nBlocks; ++i )  {    SaveStateVars( psaver, pM->ppBlocks[i] );  }}void KControlBuilder::SaveStateVars( IStateSer *psaver, KBmBase *pB ){  psaver->Write( kKeyBlockBegin );  psaver->Write( pB->BlockName );  psaver->Write( pB->TypeName );  psaver->Write( pB->H_Type );  LPCSTR pField = NULL;  LPBYTE pVarAdd = NULL;  eVarType type = evtHZ;  USHORT stringVarSize = 0;  int i = pB->GetFirstVar( SVarInfo::efVar );   while( (pField = pB->GetVar( i, pVarAdd, type, &stringVarSize )) && pField )  {    psaver->Write( kKeyField );    psaver->Write( pField );    psaver->Write( type );    switch( type )    {    case evtBool:    case evtByte:      psaver->Write( *(BYTE*)pVarAdd );      break;    case evtInt:      psaver->Write( *(int*)pVarAdd );      break;    case evtUShort:      psaver->Write( *(USHORT*)pVarAdd );      break;    case evtDouble:      psaver->Write( *(double*)pVarAdd );      break;    case evtTime:      psaver->Write( *(time_t*)pVarAdd );      break;    case evtString:      psaver->Write( (LPCSTR)pVarAdd );      break;    case evtFloat:      psaver->Write( *(float*)pVarAdd );      break;    case evtUInt64:      psaver->Write( *(UINT64*)pVarAdd );      break;    default:      ASS(0);    }  }}int KControlBuilder::RestoreState( IStateSer *psaver ){  OutputDebugString( "KControlBuilder::RestoreState...\n" );  DWORD s = GetTickCount();  if( !m_entryModule )    return 3;  char Name[64];  char TypeName[64];  DWORD H_Type;  BYTE skiparray[1024] = { 0 };  KBmBase* pBlk = NULL;  for( int i=0; 1; ++i )  {    EKeys key = eKeyNULL;    psaver->Read( key );    if( kKeyBlockBegin==key )    {      pBlk = NULL;      psaver->Read( Name );      psaver->Read( TypeName );      psaver->Read( H_Type );      pBlk = m_entryModule->QuickFindObj( Name );      if( !pBlk )        continue;      if( strcmp( TypeName, pBlk->TypeName) )      {        pBlk = NULL;        continue;      }      ASS( H_Type==pBlk->H_Type );    }    else if( kKeyField==key )    {      eVarType type = evtHZ, realType = evtHZ;      USHORT stringSize = 0;      psaver->Read( Name );      psaver->Read( type );      LPBYTE pVarAdd = NULL;      if( pBlk )      {        BYTE flags = 0;        bool b = pBlk->KBmBase::GetVar( Name, &pVarAdd, &realType, &stringSize, NULL, &flags );        ASS( b );        if( !b )          return -4;        ASS( realType==type );        if( flags&SVarInfo::efParam)          pVarAdd = skiparray;      }      else        pVarAdd = skiparray;      switch( type )      {      case evtBool:      case evtByte:        psaver->Read( *(BYTE*)pVarAdd );        break;      case evtInt:        psaver->Read( *(int*)pVarAdd );        break;      case evtUShort:        psaver->Read( *(USHORT*)pVarAdd );        break;      case evtDouble:        psaver->Read( *(double*)pVarAdd );        break;      case evtTime:        psaver->Read( *(time_t*)pVarAdd );        break;      case evtString:        if( !pBlk )          psaver->Read( (LPSTR)pVarAdd, sizeof(skiparray) );        else          psaver->Read( (LPSTR)pVarAdd, stringSize + 1 );        break;      case evtFloat:        psaver->Read( *(float*)pVarAdd );        break;      case evtUInt64:        psaver->Read( *(UINT64*)pVarAdd );        break;      default:        ASS(0);      }    }    else if( kKeyEnd==key )      break;    else    {      ASS(0);      return -5;    }  }  DWORD d = GetTickCount() - s;  char szDebug[64];  sprintf_s( szDebug, "время восстановления состояния ControlBuilder %d ms\n", d );  OutputDebugString( szDebug );  return 0;}